(() => {
  const K=CustomSalvage,esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let root=null,options=null,draft=null,tool='socket';
  function close(id,play=false){root?.remove();root=null;options.onClose(id,play);}
  function shell(title,body){root.innerHTML=`<header class="custom-header"><button data-back>‹ 返回</button><h2>${title}</h2><span>自定义 / 浮空回收</span></header>${body}`;root.querySelector('[data-back]').onclick=()=>close();}
  function notice(message,error=false){const el=root.querySelector('.custom-notice');el.textContent=message;el.classList.toggle('error',error);}
  function open(callbacks,level){options=callbacks;root?.remove();root=document.createElement('section');root.id='custom-workbench';root.className='salvage-workbench';document.body.append(root);if(level)result(level);else menu();}
  function menu(){shell('自定义',`<main class="custom-menu"><p class="custom-eyebrow">CUSTOM RECOVERY MODULE</p><h3>制作你的回收模块</h3><div class="custom-choices"><button data-create><b>＋</b><strong>创建关卡</strong><span>设置绑缚位置，摆出平衡布局</span></button><button data-import><b>⌁</b><strong>导入关卡</strong><span>输入种子，还原并保存关卡</span></button></div><p>关卡和最佳时间保存在当前浏览器。复制种子即可在其他电脑导入。</p></main>`);root.querySelector('[data-create]').onclick=editor;root.querySelector('[data-import]').onclick=importer;}
  function importer(){shell('导入关卡',`<form class="custom-import"><label>关卡种子<textarea rows="7" maxlength="10000" placeholder="粘贴 EFS1. 开头的完整种子" required></textarea></label><p>同一种子始终还原相同的棋盘、气球和升力目标。</p><p class="custom-notice" role="status"></p><button class="custom-primary">解析并保存</button></form>`);root.querySelector('form').onsubmit=e=>{e.preventDefault();try{const l=K.decode(root.querySelector('textarea').value);K.save(localStorage,l);result(l);}catch(error){notice(error.message,true);}};}
  function editor(){draft={name:'Δ-我的回收关卡',sockets:[],answer:[]};tool='socket';shell('创建关卡',`<main class="salvage-editor"><aside><label>关卡名称<input class="salvage-custom-name" value="${draft.name}" maxlength="30"/></label><p>名称以 Δ- 开头，总长不超过 15 字。</p><h3>5 × 5 回收面板</h3><div class="salvage-editor-tools"><button data-tool="socket">绑缚位置</button>${K.LIFTS.map(v=>`<button data-tool="${v}">升力 ${v} 气球</button>`).join('')}<button data-tool="erase">擦除气球</button></div><p>先设置可绑缚位置，再选择气球点击格子。再次点击绑缚位置可将其关闭。</p><p>摆出上下、左右均平衡的解答布局，即可生成关卡；开始挑战时气球会回到库存。</p><button data-all>全部允许绑缚</button><button data-clear>清空棋盘</button></aside><section><div class="salvage-author-board" role="group" aria-label="自定义回收棋盘"></div><div class="salvage-author-stats" aria-live="polite"></div></section><aside><h3>生成关卡</h3><p>气球数量和总升力目标由当前布局自动生成。只能保存已验证可解的关卡。</p><p class="custom-notice" role="status"></p><button class="custom-primary" data-save>生成种子并保存</button></aside></main>`);
    root.querySelector('input').oninput=e=>draft.name=e.target.value;
    root.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{tool=b.dataset.tool;draw();});
    root.querySelector('[data-all]').onclick=()=>{draft.sockets=Array.from({length:25},(_,i)=>[i%5,Math.floor(i/5)]);draw();};
    root.querySelector('[data-clear]').onclick=()=>{draft.sockets=[];draft.answer=[];draw();};
    root.querySelector('[data-save]').onclick=()=>{try{const l=K.create(draft);K.save(localStorage,l);result(l);}catch(error){notice(error.message,true);}};draw();
  }
  function draw(){
    root.querySelectorAll('[data-tool]').forEach(b=>{b.classList.toggle('selected',b.dataset.tool===tool);b.setAttribute('aria-pressed',String(b.dataset.tool===tool));});
    const board=root.querySelector('.salvage-author-board');board.innerHTML=Array.from({length:25},(_,i)=>{const x=i%5,y=Math.floor(i/5),socket=draft.sockets.some(p=>p[0]===x&&p[1]===y),b=draft.answer.find(b=>b.x===x&&b.y===y);return `<button data-cell="${i}" class="${socket?'socket':''} ${b?'value-'+b.lift:''}" aria-label="第${y+1}行第${x+1}列，${b?'升力 '+b.lift:socket?'可绑缚':'不可绑缚'}">${b?`<b>${b.lift}</b>`:socket?'◎':''}</button>`;}).join('');
    board.querySelectorAll('button').forEach(b=>b.onclick=()=>{const i=+b.dataset.cell,x=i%5,y=Math.floor(i/5),socket=draft.sockets.some(p=>p[0]===x&&p[1]===y);if(tool==='socket'){draft.sockets=socket?draft.sockets.filter(p=>p[0]!==x||p[1]!==y):[...draft.sockets,[x,y]];if(socket)draft.answer=draft.answer.filter(b=>b.x!==x||b.y!==y);}else if(tool==='erase')draft.answer=draft.answer.filter(b=>b.x!==x||b.y!==y);else{if(!socket){notice('请先把该格设为绑缚位置。',true);return;}draft.answer=draft.answer.filter(b=>b.x!==x||b.y!==y);draft.answer.push({x,y,lift:+tool});}notice('');draw();});
    const lift=draft.answer.reduce((s,b)=>s+b.lift,0),h=draft.answer.reduce((s,b)=>s+b.lift*(b.x-2),0),v=draft.answer.reduce((s,b)=>s+b.lift*(b.y-2),0);
    root.querySelector('.salvage-author-stats').textContent=`气球 ${draft.answer.length}　/　总升力 ${lift}　/　左右偏移 ${h}　/　上下偏移 ${v}${draft.answer.length&&h===0&&v===0?'　✓ 已平衡':''}`;
  }
  function result(l){shell('关卡已保存',`<main class="custom-import"><h3>${esc(l.code)}</h3><p>5 × 5 · ${l.balloons.length} 个气球 · 总升力 ${l.lift}</p><label>关卡种子<textarea rows="6" readonly>${esc(l.seed)}</textarea></label><p class="custom-notice" role="status">关卡已加入选择界面。种子可在其他电脑导入。</p><div class="salvage-seed-actions"><button data-copy>复制种子</button><button data-edit>编辑副本</button><button class="custom-primary" data-play>开始回收</button></div></main>`);root.querySelector('[data-play]').onclick=()=>close(l.id,true);root.querySelector('[data-copy]').onclick=async()=>{try{await navigator.clipboard.writeText(l.seed);notice('种子已复制。');}catch{root.querySelector('textarea').select();notice('请按 Ctrl+C 复制所选种子。');}};root.querySelector('[data-edit]').onclick=()=>{editor();draft={name:l.code,sockets:l.sockets.map(p=>p.slice()),answer:l.answer.map(b=>({...b}))};root.querySelector('input').value=draft.name;draw();};}
  document.addEventListener('keydown',e=>{if(root&&e.code==='Escape'){e.preventDefault();e.stopImmediatePropagation();close();}});
  window.CustomSalvageUI={open,escape:esc};
})();
